    func testVectorsMatchIndependentImplementation() throws {
        XCTAssertEqual(Self.vectors.count, 128)
        for (index, vector) in Self.vectors.enumerated() {
            let data = Data(hexString: vector.data)!
            let expected = Data(hexString: vector.ecc)!
            XCTAssertEqual(data.count, 128, "vector \(index)")
            var chunk = [UInt8](data)
            XCTAssertEqual(Data(MemoryCardECC.calculate(for: chunk)), expected, "vector \(index)")
        }
    }
    func testPageLayoutAndVerification() {        let page = Data((0..<512).map { UInt8($0 % 251) })
        let ecc = MemoryCardECC.calculatePage(page)
        XCTAssertEqual(ecc.count, 12)
        XCTAssertTrue(MemoryCardECC.verify(data: page, spare: ecc + Data(count: 4)))
        // Erased data takes the documented initial code.
        XCTAssertEqual(MemoryCardECC.calculatePage(Data(repeating: 255, count: 512)),
                       Data([0x77, 0x7F, 0x7F, 0x77, 0x7F, 0x7F, 0x77, 0x7F, 0x7F, 0x77, 0x7F, 0x7F]))
        // Any single-bit flip in data or ECC is detected.
        var bad = page
        bad[0] ^= 1
        XCTAssertFalse(MemoryCardECC.verify(data: bad, spare: ecc + Data(count: 4)))
        var badECC = ecc
        badECC[5] ^= 0x40
        XCTAssertFalse(MemoryCardECC.verify(data: page, spare: badECC + Data(count: 4)))
        // Short inputs never verify.
        XCTAssertFalse(MemoryCardECC.verify(data: Data(count: 511), spare: ecc))
        XCTAssertFalse(MemoryCardECC.verify(data: page, spare: Data(count: 11)))
    }
    func testCalculatePageIgnoresSliceBase() {
        // Integer subscripts must address the page even when the input is a
        // slice with a nonzero base (regression: implicit Data conversion
        // preserves slice indices).
        let page = Data((0..<1024).map { UInt8($0 % 251) })
        let whole = MemoryCardECC.calculatePage(Data(page[0..<512]))
        let shifted = MemoryCardECC.calculatePage(Data(page[512..<1024]))
        XCTAssertEqual(whole, MemoryCardECC.calculatePage(Data(page.prefix(512))))
        XCTAssertNotEqual(whole, shifted)
        XCTAssertEqual(shifted, MemoryCardECC.calculatePage(Data(page.suffix(512))))
    }
